const routeBody = {
  "/about": `<main><article><h1>More Than A Rescue.</h1><p>Hawkez Haven was built on one simple belief: every horse deserves the opportunity to heal, to be understood and to find where they truly belong.</p><h2>Why Hawkez Haven Exists</h2><p>Hawkez Haven was created to give horses the time, patience and understanding they deserve. Rehabilitation is about rebuilding confidence, trust and hope, at each horse's own pace.</p><p><a href="/horses">Meet our horses</a> · <a href="/adoption">Learn about adoption</a> · <a href="/support">Support Hawkez Haven</a></p></article></main>`,
  "/adoption": `<main><article><h1>A Lifetime Commitment Begins Here</h1><p>Every horse deserves the right home — not just the next home. Our adoption process is designed to match each horse with the people best suited to their future.</p><h2>The right match matters more than a quick match.</h2><p>We take time to understand each horse's temperament, needs and future goals, and we learn about your experience, setup and the life you can offer.</p><p><a href="/horses">Meet our horses</a> · <a href="/enquire/adoption">Start an adoption enquiry</a></p></article></main>`,
  "/sponsorship": `<main><article><h1>Sponsor a Rescue Horse</h1><p>Horse sponsorship helps Hawkez Haven provide ongoing care for horses who call the Haven home. Sponsorship contributes towards practical needs such as feed, hoof care, routine health care, rehabilitation and everyday welfare.</p><h2>Choose a horse to support</h2><p>Each sponsored horse has an individual story and individual needs. Sponsorship is a way to stay connected to a horse's journey without needing to own or adopt a horse yourself.</p><h2>Sponsorship levels</h2><p>Hawkez Haven offers monthly sponsorship options at different contribution levels. Each level contributes towards the ongoing costs of caring for the horses and includes different thank-you benefits depending on the selected tier.</p><h2>Where your support goes</h2><p>Horse care is ongoing. Feed, farrier care, veterinary treatment, dental care, medication, rehabilitation, equipment and safe daily management all add up. Sponsorship helps us keep providing that care consistently.</p><h2>Support from anywhere in New Zealand</h2><p>You can sponsor a Hawkez Haven horse from anywhere in New Zealand. The connection is about supporting their wellbeing and following their story, wherever you are.</p><p><a href="/sponsorship">View sponsorship options</a> · <a href="/horses">Meet the horses</a> · <a href="/contact">Contact Hawkez Haven</a></p></article></main>`,
  "/foster": `<main><article><h1>Foster a Rescue Horse</h1><p>Fostering can give a Hawkez Haven horse a safe, stable place to live while they recover, rebuild confidence or wait for the right next chapter.</p><h2>What fostering means</h2><p>A foster home provides appropriate day-to-day care, a suitable environment, consistent routine and communication with Hawkez Haven. Every horse is different, so arrangements are considered around the horse's health, temperament, management needs and the foster home's property and experience.</p><h2>Hawkez Haven remains involved</h2><p>Foster placement does not transfer ownership. Hawkez Haven remains involved in the horse's welfare and works with the foster home throughout the arrangement. Veterinary, feed and other practical responsibilities are discussed clearly before a horse is placed.</p><h2>Finding the right match</h2><p>We look at more than available grazing. Fencing, shelter, water, herd compatibility, handling experience, daily routine and the ability to follow the horse's management plan all matter.</p><h2>How to apply</h2><p>Start with a foster enquiry and tell us about your location, property, horse experience and the situation you can provide. We can then talk through the current horses and whether fostering may be appropriate.</p><p><a href="/enquire/foster">Make a foster enquiry</a> · <a href="/horses">Meet the horses</a> · <a href="/contact">Contact Hawkez Haven</a></p></article></main>`,
  "/volunteer": `<main><article><h1>Volunteer with Hawkez Haven</h1><p>Volunteers help with the practical work behind a small, welfare-focused horse rescue in Ashhurst, Manawatū. There are opportunities to help with horse care, property work, gear, rehabilitation support and supervised horse sessions.</p><h2>What volunteers can do</h2><p>Depending on experience and current needs, volunteers may help with feeding routines, grooming, paddock care, cleaning and organising equipment, working bees, or supporting calm groundwork and handling under guidance.</p><h2>Experience and safety</h2><p>You do not necessarily need years of horse experience. Some roles are suitable for enthusiastic helpers with appropriate supervision, while sensitive horse handling and rehabilitation support require suitable experience or training. Closed-toe footwear and practical outdoor clothing are essential.</p><h2>What to expect</h2><p>Hawkez Haven uses a patient, welfare-first approach. Volunteers receive an induction to the property, horses, safety expectations and ways of working before taking on responsibilities.</p><h2>Volunteer in Ashhurst</h2><p>We are based on a private property in Ashhurst, near Palmerston North. Volunteer opportunities are local and arranged around current rescue needs rather than a fixed public timetable.</p><p><a href="/enquire/volunteer">Make a volunteer enquiry</a> · <a href="/contact">Contact Hawkez Haven</a></p></article></main>`,
  "/education": `<main><article><h1>Horse Education &amp; Experiences</h1><p>Explore horse education, horsemanship and practical experiences at Hawkez Haven, with welfare and understanding at the heart of every lesson.</p><h2>Learn With The Horse In Mind.</h2><p>Our education and horsemanship experiences are designed to build knowledge, confidence, safety and a better understanding of horses. Sessions cover horse care, groundwork, connection, riding, rescue and rehabilitation, and thoughtful time with horses.</p><p><a href="/enquire/experiences">Make an education or experience enquiry</a> · <a href="/contact">Contact Hawkez Haven</a></p></article></main>`,
  "/support": `<main><article><h1>Support Hawkez Haven</h1><p>Hawkez Haven is a small independent horse rescue, and the everyday costs of caring for horses never stop. Support helps provide feed, hoof care, veterinary treatment, equipment, rehabilitation and the practical things that keep a working rescue running.</p><h2>Ways to help</h2><p>You can make a one-off contribution, sponsor a specific horse-care need, support feed and hay, contribute towards veterinary or hoof care, or choose another practical item from our support options.</p><h2>Small contributions matter</h2><p>There is no single amount that makes a difference. A bale of hay, a hoof trim, worming treatment or contribution towards an emergency veterinary fund can all become part of a horse's care.</p><h2>Support a New Zealand horse rescue</h2><p>Hawkez Haven is based in Ashhurst, Manawatū, New Zealand. Every contribution helps us continue providing a safe, welfare-focused environment for the horses in our care.</p><p><a href="/support">Choose a way to help</a> · <a href="/sponsorship">Sponsor a horse</a> · <a href="/contact">Contact Hawkez Haven</a></p></article></main>`,
  "/contact": `<main><article><h1>Contact Hawkez Haven</h1><p>Contact us about horse rescue, adoption, sponsorship, volunteering, fostering, lessons and other enquiries.</p><p><a href="/enquire/general">Start a general enquiry</a></p></article></main>`,
  "/faq": "<main><article><h1>Frequently Asked Questions</h1><p>Answers about Hawkez Haven horse rescue, rehabilitation, adoption, volunteering, support and horsemanship education in New Zealand.</p><h2>About Hawkez Haven</h2><h3>What is Hawkez Haven – Second Chances?</h3><p>Hawkez Haven is a New Zealand equine rescue, rehabilitation, education and responsible rehoming organisation with a welfare-first approach.</p><h3>Where is Hawkez Haven located?</h3><p>Hawkez Haven is based in Ashhurst, Manawatū, New Zealand.</p><h3>What does Hawkez Haven do?</h3><p>Hawkez Haven rescues horses in need, supports physical and emotional recovery, provides rehabilitation and retraining where appropriate, and carefully matches suitable horses with responsible homes.</p><h3>What types of horses does Hawkez Haven help?</h3><p>Hawkez Haven works with horses who need rescue, rehabilitation or a carefully considered next chapter, including horses affected by neglect, injury, difficult experiences or the challenges of life after racing. Some may be senior, companion-only or have ongoing physical limitations.</p><h2>Rescue &amp; Rehabilitation</h2><h3>What happens when a horse arrives at Hawkez Haven?</h3><p>The horse's health, behaviour, handling needs and welfare are considered so their care can be shaped around what they actually need.</p><h3>How is a rescued horse assessed?</h3><p>Assessment is individual and considers history, health, temperament, behaviour, confidence, handling and practical needs.</p><h3>Does every horse receive veterinary assessment?</h3><p>Every horse entering Hawkez Haven is assessed according to its individual health, history and circumstances, and veterinary care is sought whenever it is required. Depending on the horse, this can include assessment or treatment relating to weight and body condition, injuries or previous injuries, lameness or mobility concerns, feet and hoof condition, dental health, skin or other visible health problems, parasites and worming requirements, nutrition and dietary needs, medications or ongoing treatment, previous racing, riding or work history, and any other concern identified during rehabilitation. The type and level of veterinary care is not identical for every horse — some may require extensive veterinary intervention while another may require routine care and monitoring.</p><h3>How long does rehabilitation take?</h3><p>There is no fixed timeline. Each horse's rehabilitation is shaped around their individual needs, health, confidence and progress.</p><h3>What happens when a horse isn't suitable for rehoming?</h3><p>Not every horse that comes into Hawkez Haven will be suitable for rehoming, and being unable to be rehomed does not mean that horse is unwanted or has failed. Some horses may have permanent physical limitations, ongoing medical needs, significant behavioural or emotional needs, age-related requirements, or simply be unsuitable for the type of home available to them. Hawkez Haven looks at what that individual horse actually needs for the rest of its life. This may mean remaining under Hawkez Haven's care, remaining as a companion horse, living a non-ridden life, requiring ongoing veterinary, hoof, dietary or management support, or being placed only with a home that can genuinely meet its specific needs. A horse will not be placed into an unsuitable home simply to make room for another horse.</p><h3>Do you help senior horses?</h3><p>Yes. Hawkez Haven considers companion and non-ridden placements for senior horses where appropriate.</p><h3>Do you help horses with injuries or ongoing limitations?</h3><p>Yes. Horses with injuries, physical limitations or ongoing management needs may require a different rehabilitation pathway or a specialised home.</p><h2>Adoption &amp; Rehoming</h2><h3>How does adoption work?</h3><p>Adoption begins with an enquiry and open conversation, followed by suitability discussions, meeting the horse, adoption arrangements and ongoing support.</p><h3>What are the requirements to adopt a horse?</h3><p>Hawkez Haven is looking for genuine, committed homes — not temporary homes, impulse purchases or placements based simply on wanting a horse. Adoption is intended to be a long-term, lifelong commitment wherever possible. Before adopting, applicants need to be confident that they are prepared to care for the horse throughout its life, including through changes in circumstances and the horse's changing needs as it ages. An approved adopter must be willing to provide safe, appropriate accommodation and daily care, meet the horse's feed, hoof, dental, veterinary and general welfare needs, provide appropriate companionship and management, have the experience, knowledge or support necessary for that particular horse, respect any restrictions or special requirements relating to the horse, communicate honestly with Hawkez Haven, agree to Hawkez Haven's Approved Home Agreement and associated adoption documentation, and commit to the horse's long-term welfare. Every horse is different, so the requirements aren't identical for every adoption. Approval is based on whether the individual horse and individual home are a suitable match.</p><h3>Do you require references?</h3><p>References or additional information may be requested when needed to assess a proposed home.</p><h3>Can a beginner adopt a rescue horse?</h3><p>Yes, potentially — but being a beginner does not automatically make a horse suitable for you. Some horses may be appropriate for a less experienced owner when the right support system is in place, while others will require an experienced handler. Support may include a qualified riding instructor, an experienced horse-owning friend, a knowledgeable sibling or parent, a partner with appropriate horse experience, or another trusted local horse professional. The important thing is whether you have the support, willingness to learn and commitment required to safely care for the particular horse you're applying for.</p><h3>How do you decide which home is suitable for each horse?</h3><p>Matching is based on compatibility between the horse's needs and the adopter's experience, setup, lifestyle and ability to provide long-term care.</p><h3>What happens if an adopter can no longer keep the horse?</h3><p>Hawkez Haven's first priority is making sure the horse remains safe. If circumstances change and an adopter can no longer keep their horse, the adopter must contact Hawkez Haven rather than simply selling, giving away or passing the horse on without communication. The horse can be returned to Hawkez Haven for assessment and the next appropriate placement to be considered, or the adopter may be able to help Hawkez Haven find a suitable new home themselves, provided the proposed home is approved and is willing to enter into the same required agreements and welfare conditions. Any new placement must continue to protect the horse's welfare and maintain the information and history needed to safely track its future.</p><h3>Why are Hawkez Haven horses placed in approved homes?</h3><p>Where a rescue horse goes next can be just as important as what happens to it while it is in rescue. Horses can be sold, given away or passed on with good intentions, only for circumstances to change. A horse may end up with someone who does not understand its needs, is inexperienced with its temperament, expected it to perform at a level it cannot safely manage, loses interest, or does not understand the horse's previous trauma or limitations. Sometimes the horse and human simply do not connect. A horse may lose confidence, a rider may lose confidence, and handling mistakes can escalate. A horse that was previously progressing can begin to regress and acquire a label such as difficult or problematic, which can lead to another unsuitable placement. In the worst circumstances, a horse can continue moving from home to home, become neglected, lose condition, receive inadequate care, or end up in a situation where its welfare is seriously compromised. The approved-home process is intended to interrupt that cycle by establishing who the horse is, what the horse needs, who the person applying is, what they can realistically provide, and whether they are actually going to work together. The goal is a safe, appropriate and lasting connection rather than simply getting a horse out of rescue quickly. That is why Hawkez Haven uses approved-home agreements and why adopters are expected to remain accountable for the horse's welfare. The horse's story should not end when it leaves Hawkez Haven — we want to know that the next chapter is a safe one.</p><h2>Volunteering</h2><h3>How can I volunteer?</h3><p>Volunteer enquiries can be made through the Hawkez Haven volunteer page.</p><h3>What sort of volunteer work is available?</h3><p>Roles can include horse care and husbandry, rehabilitation support, gear and yard care, and session support.</p><h3>Do I need horse experience to volunteer?</h3><p>Not necessarily. Some roles are suitable for enthusiastic helpers with appropriate supervision, while sensitive horse handling and rehabilitation support value prior experience.</p><h3>How do I apply?</h3><p>Use the volunteer enquiry options on the Hawkez Haven website to get in touch.</p><h2>Supporting Hawkez Haven</h2><h3>How can I donate?</h3><p>Support Hawkez Haven through the Support page, including one-off giving and specific horse-care needs.</p><h3>Can I sponsor a horse?</h3><p>Yes. Hawkez Haven offers rescue-horse sponsorship to help support the care of individual horses.</p><h3>Can I donate hay, feed or equipment?</h3><p>Hay, feed, veterinary care, hoof care and practical equipment are ongoing needs. Contact Hawkez Haven first about a specific physical donation so the current need can be confirmed.</p><h3>How can businesses support Hawkez Haven?</h3><p>Businesses interested in supporting rescue, rehabilitation, education or practical horse-care needs can contact Hawkez Haven to discuss ways to help.</p><h2>Education</h2><h3>Does Hawkez Haven offer horsemanship education?</h3><p>Yes. Hawkez Haven offers horse education, horsemanship and practical experiences centred on welfare, safety and understanding.</p><h3>What do students learn?</h3><p>Depending on the experience, students can learn about horse care, body language, welfare, groundwork, communication, handling, life after racing and rescue rehabilitation.</p><h3>Do you offer children's programmes?</h3><p>Yes. Hawkez Haven offers experiences for school-aged children and families, with suitable sessions and age requirements listed on the Education &amp; Horsemanship page.</p><p><a href='/about'>About Hawkez Haven</a> · <a href='/horses'>Meet the horses</a> · <a href='/adoption'>Horse adoption</a> · <a href='/volunteer'>Volunteer</a> · <a href='/education'>Education &amp; Horsemanship</a> · <a href='/support'>Support Hawkez Haven</a></p></article></main>",
  "/gift-card": `<main><article><h1>Give a Hawkez Haven Gift Card</h1><p>A Hawkez Haven gift card is a way to give someone a meaningful horse experience while supporting rescue, rehabilitation and education work in New Zealand.</p><h2>A gift with a purpose</h2><p>Gift cards can support experiences and activities connected with Hawkez Haven's education and horsemanship programme. They can make a thoughtful gift for someone who loves horses, wants to learn more about horse care, or would enjoy spending time learning with horses in a calm environment.</p><h2>Horse experiences and education</h2><p>Hawkez Haven offers practical education centred on horse welfare, body language, groundwork, handling, horsemanship and responsible partnership. Suitable experiences depend on age, experience, horse welfare and current programme availability.</p><h2>How the gift card works</h2><p>Choose an amount, enter the recipient details and complete payment through the available payment option. The gift card reference is generated for the purchase, and Hawkez Haven can use the information provided to confirm the gift and arrange the next steps.</p><h2>A local gift from Hawkez Haven</h2><p>Hawkez Haven is based in Ashhurst, Manawatū, near Palmerston North. Experiences are arranged by appointment so the horses' routines and welfare remain the priority.</p><p><a href="/gift-card">Purchase a gift card</a> · <a href="/education">Explore education &amp; horsemanship</a> · <a href="/contact">Contact Hawkez Haven</a></p></article></main>`,
  "/hub/horse-adoption-nz": `<main><article><p>Hawkez Haven Guide</p><h1>Horse Adoption NZ: How to Adopt a Rescue Horse in New Zealand</h1><p>A practical guide to adopting a rescue horse in New Zealand — from finding the right match and preparing your property to understanding the ongoing commitment, costs and welfare responsibilities.</p><img src="/images/hero_image_hub.png" alt="Rescue horse at Hawkez Haven – Second Chances in New Zealand" width="1200" height="800" /><h2>What Does Horse Adoption Mean in New Zealand?</h2><p>Horse adoption means taking responsibility for a horse's ongoing welfare and providing an appropriate home, management, companionship, care and training for the long term. Responsible adoption is about compatibility rather than impulse.</p><h2>Finding a Horse Rescue in New Zealand</h2><p>If you're looking for a <strong>horse rescue in New Zealand</strong>, start by looking beyond the horse's photo or asking only what riding ability they have. A responsible rescue should be able to explain the horse's known history, current needs, rehabilitation progress and the type of home they believe will suit that individual.</p><p>Horse rescue in NZ can involve owner surrender, neglect, hardship, off-the-track horses, injury rehabilitation and horses needing a safe reset before rehoming. Not every rescue horse will be ready to ride, and not every horse will be suitable for every home.</p><p>When considering <strong>horse adoption in New Zealand</strong>, look for clear information about the horse, honest disclosure of known health and behavioural history, a thoughtful matching process and a responsible pathway if circumstances change.</p><p>At Hawkez Haven – Second Chances, our approach to horse rescue, rehabilitation and rehoming is centred on welfare first. We take time to understand each horse as an individual and to find an approved home that can genuinely meet their needs.</p><h2>Finding the Right Rescue Horse</h2><p>Consider your riding and handling experience, confidence, property and facilities, existing horses, available time, budget, riding goals and access to veterinary and farrier support. The right match is the horse whose needs you can realistically meet.</p><h2>The Horse Adoption Process</h2><p>At Hawkez Haven, adoption begins with an enquiry and open conversation, followed by suitability discussions, meeting the horse, formalising the adoption arrangements and planning the horse's transition into their new home.</p><h2>Preparing Your Property</h2><p>Check fencing, gates, wire, trees, ditches, water, feed areas, shelter, mud, machinery, toxic plants and other hazards. Horses also need appropriate forage, water, companionship and protection from weather.</p><h2>The Real Cost of Horse Adoption</h2><p>An adoption contribution is only one part of the commitment. Plan for hay and pasture, feed, farrier care, dental care, veterinary care, parasite management, equipment, transport, property maintenance and emergencies.</p><h2>Horse Welfare in New Zealand</h2><p>People responsible for horses have obligations under New Zealand animal welfare law and relevant codes of welfare. Identification, health care, shelter, food, water, handling and protection from avoidable suffering are all important parts of responsible ownership.</p><h2>Connection Before Correction</h2><p>At Hawkez Haven, rehabilitation centres on communication, patience and understanding. A successful second chance is about finding a partnership in which the horse can stay safe, understood and valued.</p><p><a href="/horses">Meet the horses</a> · <a href="/adoption">Learn about the adoption process</a> · <a href="/enquire/adoption">Start an adoption enquiry</a></p></article></main>`,
  "/horse-rescue-new-zealand": `<main><article><p>Hawkez Haven – Second Chances</p><h1>Horse Rescue New Zealand</h1><p>Rescue, rehabilitation, rehoming and second chances — with welfare at the centre of every decision.</p><img src="/images/hero_image_hub.png" alt="Rescue horse at Hawkez Haven – Second Chances in New Zealand" width="1200" height="800" /><h2>What Does Horse Rescue Actually Involve?</h2><p>Horse rescue in New Zealand is not simply about taking a horse out of a difficult situation. It is about understanding what that horse needs next. Hawkez Haven approaches rescue, rehabilitation and responsible rehoming around the individual horse.</p><p>Rescue can involve safe accommodation, forage and water, health and hoof care, nutrition, observation, handling, confidence building, groundwork and careful planning for the horse’s future.</p><h2>How Horses Come Into Rescue</h2><p>Horses may enter rescue through owner surrender, financial hardship, changed circumstances, injury, neglect, abandonment or difficult previous experiences. Thoroughbreds transitioning from racing or another career may also need time and support while they learn a different routine.</p><p>Early communication can matter. Asking for help before a situation becomes an emergency may create safer options for the horse.</p><p><a href="/contact">Contact Hawkez Haven</a> to start a conversation about a horse’s circumstances.</p><h2>Rehabilitation Comes Before Rehoming</h2><p>A rescue horse is not automatically ready for adoption when they arrive. Some need physical recovery, hoof or dental care, nutrition changes, veterinary support, confidence building, groundwork or simply time to settle and show who they are.</p><p>The purpose is not to make every horse rideable or marketable. It is to improve welfare and understand the individual horse. Sometimes that leads to adoption; sometimes another outcome is safer.</p><h2>Responsible Horse Rehoming in New Zealand</h2><p>When a horse is ready for rehoming, suitability matters more than speed. Responsible matching considers the horse’s history, health, behaviour and needs alongside the prospective home’s experience, facilities, time and ability to provide ongoing care.</p><p>Hawkez Haven uses an <strong>approved-home</strong> approach because the best placement is the one that can genuinely meet the individual horse’s needs.</p><p><a href="/adoption">Learn about horse adoption at Hawkez Haven</a> · <a href="/horses">Meet the horses</a></p><h2>What If a Placement Doesn't Work?</h2><p>Sometimes a placement that looked suitable on paper does not work in real life. Responsible rehoming needs a pathway for what happens next. Hawkez Haven asks adopters to contact us if they can no longer keep their horse rather than passing the horse on without communication.</p><h2>Horse Rescue in Manawatū and Palmerston North</h2><p>Hawkez Haven is a working horse rescue in the Manawatū region of New Zealand, serving the local community while also considering horses and approved homes from further afield when circumstances and capacity allow.</p><p>Because rescue work happens on a private working property, visits are arranged by appointment. If you are looking for a <strong>horse rescue near you</strong>, need to discuss surrender, or want to understand whether a rescue horse may be suitable for your home, the best first step is to contact us and explain your situation.</p><p><a href="/contact">Contact Hawkez Haven about horse rescue</a> or <a href="/horses">meet the horses currently in our care</a>.</p><h2>How You Can Help Horse Rescue</h2><p>Rescue is a community effort. You can volunteer, sponsor a horse, foster where appropriate, contribute practical resources, share responsible education or offer an approved home when you are genuinely ready for the commitment.</p><p><a href="/volunteer">Volunteer</a> · <a href="/support">Support Hawkez Haven</a> · <a href="/foster">Foster a rescue horse</a></p><h2>Horse Rescue, Rehabilitation and Second Chances</h2><p>Every rescue horse has a story before they arrive. Our job is not to erase that story. It is to help create a safer next chapter. The outcome is individual. The standard is the same: <strong>welfare first.</strong></p><p><a href="/hub/unwanted-horses-nz">What Happens to Unwanted Horses in New Zealand?</a> · <a href="/hub/horse-adoption-nz">Horse Adoption NZ Guide</a> · <a href="/adoption">Adoption</a></p></article></main>`,
  "/hub/unwanted-horses-nz": `<main><article><p>Hawkez Haven Information Hub</p><h1>What Happens to Unwanted Horses in New Zealand?</h1><p>When a horse can no longer stay where it is, the next step matters. This guide explains responsible surrender, rescue, rehabilitation and rehoming in New Zealand.</p><img src="/images/hero_image_hub.png" alt="Rescue horse at Hawkez Haven – Second Chances in New Zealand" width="1200" height="800" /><h2>What Can Make a Horse “Unwanted”?</h2><p>A horse can become unwanted because an owner's circumstances change, costs become unmanageable, an injury changes what the horse can do, a previous placement fails, or the horse's needs become greater than the home can safely provide.</p><p>Other horses enter rescue because of neglect, abandonment, poor condition or a history that has left them needing time and careful rehabilitation. Each horse needs to be assessed as an individual.</p><h2>Owner Surrender and Hardship</h2><p>Sometimes the most responsible thing an owner can do is admit that they can no longer provide what their horse needs. A responsible surrender means being honest about the horse's history, behaviour, health, handling, diet, medication and known limitations.</p><p>Asking for help is not automatically a failure. Early communication can give a horse a safer path before a difficult situation becomes a welfare crisis.</p><p><a href="/contact">Contact Hawkez Haven</a> if you need to discuss a horse's circumstances.</p><h2>When Neglect Has Already Happened</h2><p>Some horses arrive after their welfare has deteriorated. Rehabilitation may involve poor body condition, painful feet, skin problems, untreated wounds, dental issues, fear, loss of confidence or a combination of physical and behavioural needs.</p><p>The first goal is not to make the horse useful again. It is to make the horse safe, comfortable and stable. That can mean veterinary assessment, nutrition changes, hoof rehabilitation, dental care, appropriate parasite management, safe handling, groundwork, rest and patience.</p><h2>Off-the-Track Thoroughbreds and Horses with a Past</h2><p>Horses leaving racing or other previous careers may need time to learn a different routine, develop new skills and understand a different kind of human partnership. A horse's background does not tell you everything about the individual in front of you.</p><p><a href="/horses">Meet the horses at Hawkez Haven</a> and follow their different journeys.</p><h2>Why a Rescue Horse May Not Be Available Straight Away</h2><p>Taking a horse into rescue does not mean that horse is immediately ready for adoption. A new arrival may need quiet observation, health assessment, rehabilitation, confidence building or groundwork before anyone can responsibly understand what type of home will suit them.</p><p>Responsible rescue is not about moving horses through as quickly as possible. It is about welfare and finding a realistic long-term match.</p><h2>What Responsible Rehoming Looks Like</h2><p>When a horse is ready for a new home, the process should involve more than a photograph and a price. Responsible rehoming considers known history, health and behaviour, the prospective home, experience, facilities, ongoing costs, references where appropriate, and what happens if circumstances change.</p><p>At Hawkez Haven, the aim is an <strong>approved home</strong> that is genuinely compatible with the individual horse.</p><p><a href="/adoption">Learn how Hawkez Haven approaches horse adoption and approved-home matching.</a></p><h2>What If the Placement Doesn't Work?</h2><p>Sometimes a placement that looked suitable on paper does not work in real life. The horse and person may not connect, circumstances may change, or the horse's needs may turn out to be different from what was expected. Responsible rehoming should include a clear pathway for what happens next.</p><p>At Hawkez Haven, adopters are expected to contact us if they can no longer keep their horse rather than simply passing the horse on without communication. The horse's welfare remains the priority.</p><h2>If You Can No Longer Keep Your Horse</h2><p>If you are searching for what to do with an unwanted horse in New Zealand, don't wait until the situation becomes dangerous if you can ask for help earlier. Prepare an honest summary of the horse's age, history, health, feed, medications, behaviour, handling, riding history and known problems, then contact appropriate welfare organisations or experienced rescue services.</p><p>Not every organisation will have capacity to take a horse immediately, but early communication can help identify safer options.</p><p><a href="/contact">Start a conversation with Hawkez Haven</a> about surrender or rehoming options.</p><h2>A Second Chance Is More Than a New Address</h2><p>A second chance can mean months of rehabilitation, rebuilding trust, improving physical condition, learning new skills and waiting for the right home rather than the first available home. Sometimes the best outcome is adoption. Sometimes it is a long-term lease, a companion role or a permanent place with the rescue. The right answer depends on the horse.</p><p><strong>The goal is not simply to move a horse on. The goal is to give that horse the safest, most appropriate next chapter we can.</strong></p><p><a href="/hub">Back to The Hub</a> · <a href="/hub/horse-adoption-nz">Horse Adoption Guide</a> · <a href="/adoption">Adoption</a> · <a href="/support">Support Hawkez Haven</a></p></article></main>`,
  "/privacy": `<main><article><h1>Privacy Statement</h1><p>Hawkez Haven – Second Chances respects your privacy. This statement explains what personal information we collect, why we collect it, how we use it, and how you can contact us about your information.</p><p><a href="/terms">Read our Terms of Use</a> · <a href="/contact">Contact Hawkez Haven</a></p></article></main>`,
  "/terms": `<main><article><h1>Terms of Use</h1><p>These terms explain the conditions that apply to use of the Hawkez Haven website, enquiries, bookings, horse adoption, experiences and support services.</p><p><a href="/privacy">Read our Privacy Statement</a> · <a href="/contact">Contact Hawkez Haven</a></p></article></main>`,
};

function escapeHtml(value) {
  return value.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;").replaceAll("'", "&#39;");
}

function upsertHeadTag(html, pattern, tag) {
  const headEnd = html.search(/<\/head>/i);
  if (headEnd === -1) throw new Error("Cannot prerender SEO metadata: </head> is missing from dist/index.html");
  const head = html.slice(0, headEnd);
  const tail = html.slice(headEnd);
  const cleanedHead = head.replace(pattern, "");
  return `${cleanedHead}${tag}\n  ${tail}`;
}

function structuredData(meta, path) {
  const canonical = `${site}${path}`;
  const graph = [
    { "@type": "WebSite", "@id": `${site}/#website`, url: `${site}/`, name: "Hawkez Haven", description: "Hawkez Haven is a New Zealand horse rescue and rehabilitation organisation.", inLanguage: "en-NZ" },
    { "@type": "AnimalShelter", "@id": `${site}/#organisation`, name: "Hawkez Haven", url: `${site}/`, logo: `${site}/images/hawkez-logo-transparent.png`, description: "Independent equine rescue, rehabilitation and connection-based horsemanship and horse welfare organisation in New Zealand.", areaServed: "New Zealand", slogan: "Where Second Chances Find Their Stride" },
    { "@type": "WebPage", "@id": `${canonical}#webpage`, url: canonical, name: meta.title, description: meta.description, inLanguage: "en-NZ", isPartOf: { "@id": `${site}/#website` }, about: { "@id": `${site}/#organisation` } },
  ];
  return `<script id="hawkez-haven-prerendered-schema" type="application/ld+json">${JSON.stringify({ "@context": "https://schema.org", "@graph": graph })}</script>`;
}

function renderPage(path, meta, body = "") {
  const canonical = `${site}${path}`;
  let html = template;
  if (path !== "/") html = html.replace(/<script\s+type=["']application\/ld\+json["'][^>]*>[\s\S]*?<\/script>\s*/gi, "");
  html = upsertHeadTag(html, /<title>[\s\S]*?<\/title>/gi, `<title>${escapeHtml(meta.title)}</title>`);
  html = upsertHeadTag(html, /<meta\s+name=["']description["'][^>]*>/gi, `<meta name="description" content="${escapeHtml(meta.description)}" />`);
  html = upsertHeadTag(html, /<link\s+rel=["']canonical["'][^>]*>/gi, `<link rel="canonical" href="${canonical}" />`);
  html = upsertHeadTag(html, /<meta\s+property=["']og:title["'][^>]*>/gi, `<meta property="og:title" content="${escapeHtml(meta.title)}" />`);
  html = upsertHeadTag(html, /<meta\s+property=["']og:description["'][^>]*>/gi, `<meta property="og:description" content="${escapeHtml(meta.description)}" />`);
  if (path !== "/") html = upsertHeadTag(html, /<script id=["']hawkez-haven-prerendered-schema["'][\s\S]*?<\/script>\s*/gi, structuredData(meta, path));
  if (body) html = html.replace('<div id="root"></div>', `<div id="root">${body}</div>`);
  return { html, output: path === "/" ? resolve(distDir, "index.html") : resolve(distDir, path.slice(1), "index.html") };
}

const horseLinks = Object.entries(horsePages).map(([id, horse]) => `<li><a href="/horses/${id}">${escapeHtml(horse.name)}</a> — ${escapeHtml(horse.description)}</li>`).join("\n");
const homepageBody = `<main><article><header><p>Aotearoa · Equine Rescue &amp; Rehabilitation</p><h1>Where Second Chances Find Their Stride</h1><p>Connection Before Correction.</p><p>Every horse deserves the chance to heal, trust again and find the home they were always meant to have.</p></header><section><h2>A place built on patience, trust and second chances.</h2><p>Hawkez Haven – Second Chances is an independent equine rescue, rehabilitation and rehoming service based in Ashhurst, Manawatū, New Zealand. We care for horses who need time, understanding, practical rehabilitation and a safe place to begin again.</p><p>Our work starts with the individual horse. Some arrive through owner surrender when their circumstances have changed. Some are Thoroughbreds coming from racing or other previous careers. Others arrive because their health, behaviour, confidence or welfare needs have become more than their previous home can safely manage.</p><p>We do not believe rehabilitation should be rushed to meet a deadline. A horse may need veterinary care, improved nutrition, farrier work, dental care, groundwork, confidence building, careful retraining or simply a period of quiet stability. We build a plan around the horse in front of us and adjust it as they heal and show us what they need.</p><p>When a horse is suitable for rehoming, Hawkez Haven looks for an approved home that can genuinely meet that individual horse's needs. Matching matters more than moving a horse quickly, and our welfare-first approach continues beyond the day a horse leaves the Haven.</p><p>Not every horse is destined for rehoming. Some become permanent residents, teaching horses or companion horses whose place at Hawkez Haven is secure. Our education programme also gives people the opportunity to learn about horse care, body language, groundwork, horsemanship and responsible partnership in a calm, practical environment.</p><p>Hawkez Haven is based on a private property in Ashhurst, just outside Palmerston North in the Manawatū region. Visits, horse meetings and experiences are arranged by appointment because this is a working rescue and the horses' routines and welfare come first.</p></section><nav aria-label="Hawkez Haven main resources"><h2>Explore Hawkez Haven</h2><ul><li><a href="/horses">Meet Our Horses</a></li><li><a href="/adoption">Horse Adoption</a></li><li><a href="/sponsorship">Sponsor a Rescue Horse</a></li><li><a href="/foster">Foster a Rescue Horse</a></li><li><a href="/volunteer">Volunteer</a></li><li><a href="/education">Horse Education &amp; Horsemanship</a></li><li><a href="/about">About Hawkez Haven</a></li><li><a href="/support">Support Hawkez Haven</a></li><li><a href="/contact">Contact Hawkez Haven</a></li><li><a href="/gift-card">Hawkez Haven Gift Cards</a></li><li><a href="/privacy">Privacy Statement</a></li><li><a href="/terms">Terms of Use</a></li></ul></nav></article></main>`;
const horsesBody = `<main><article><h1>Our Horses</h1><p>Meet the horses of Hawkez Haven and follow their individual journeys through rescue, rehabilitation, recovery and responsible rehoming.</p><section aria-labelledby="horse-stories"><h2 id="horse-stories">Horse Rescue Stories</h2><ul>${horseLinks}</ul></section><p><a href="/adoption">Learn about horse adoption</a> · <a href="/support">Support Hawkez Haven</a> · <a href="/contact">Contact Hawkez Haven</a></p></article></main>`;

const generatedFiles = [];
for (const [path, meta] of Object.entries(pages)) {
  const body = path === "/" ? homepageBody : path === "/horses" ? horsesBody : routeBody[path] || "";
  const { html, output } = renderPage(path, meta, body);
  await mkdir(dirname(output), { recursive: true });
  await writeFile(output, html, "utf8");
  generatedFiles.push([output, meta]);
}

for (const [id, horse] of Object.entries(horsePages)) {
  const path = `/horses/${id}`;
  const horseMeta = { ...horse, canonical: path };
  const body = `<main><article><h1>${escapeHtml(horse.name)}</h1><p>${escapeHtml(horse.description)}</p><img src="${escapeHtml(horse.image)}" alt="${escapeHtml(horse.name)} at Hawkez Haven" width="1200" height="800" /><nav aria-label="Horse navigation"><a href="/horses">Back to Our Horses</a> · <a href="/adoption">Horse Adoption</a> · <a href="/support">Support Hawkez Haven</a></nav></article></main>`;
  let { html, output } = renderPage(path, horseMeta, body);
  html = html.replace(/<script id=["']hawkez-haven-prerendered-schema["'][\s\S]*?<\/script>\s*/gi, "");
  const horseSchema = {
    "@context": "https://schema.org",
    "@graph": [
      { "@type": "WebSite", "@id": `${site}/#website`, url: `${site}/`, name: "Hawkez Haven", inLanguage: "en-NZ" },
      { "@type": "AnimalShelter", "@id": `${site}/#organisation`, name: "Hawkez Haven", url: `${site}/` },
      { "@type": "WebPage", "@id": `${site}${path}#webpage`, url: `${site}${path}`, name: horse.title, description: horse.description, inLanguage: "en-NZ", isPartOf: { "@id": `${site}/#website` }, about: { "@id": `${site}${path}#animal` } },
      { "@type": "Animal", "@id": `${site}${path}#animal`, name: horse.name, description: horse.description },
    ],
  };
  html = html.replace(/<\/head>/i, `<script id="hawkez-haven-prerendered-schema" type="application/ld+json">${JSON.stringify(horseSchema)}</script>\n  </head>`);
  await mkdir(dirname(output), { recursive: true });
  await writeFile(output, html, "utf8");
  generatedFiles.push([output, horseMeta]);
}
